    idx = 0
    N = int(data[idx]); idx += 1
    M = int(data[idx]); idx += 1
    X = int(data[idx]); idx += 1

    adj_fwd = [[] for _ in range(N + 1)]
    adj_bwd = [[] for _ in range(N + 1)]

    for _ in range(M):
        u = int(data[idx]); idx += 1
        v = int(data[idx]); idx += 1
        adj_fwd[u].append(v)
        adj_bwd[v].append(u)

    INF = float('inf')
    # dist[v][p]: minimum cost to be at vertex v with parity p (0 = original, 1 = reversed)
    dist0 = [INF] * (N + 1)
    dist1 = [INF] * (N + 1)
    dist0[1] = 0

    pq = [(0, 1, 0)]

    while pq:
        d, v, p = heapq.heappop(pq)
        if p == 0:
            if d > dist0[v]:
                continue
        else:
            if d > dist1[v]:
                continue

        if v == N:
            print(d)
            return

        # Move along an edge in current orientation
        if p == 0:
            nd = d + 1
            for u in adj_fwd[v]:
                if nd < dist0[u]:
                    dist0[u] = nd
                    heapq.heappush(pq, (nd, u, 0))
        else:
            nd = d + 1
            for u in adj_bwd[v]:
                if nd < dist1[u]:
                    dist1[u] = nd
                    heapq.heappush(pq, (nd, u, 1))

        # Reverse all edges
        nd = d + X
        if p == 0:
            if nd < dist1[v]:
                dist1[v] = nd
                heapq.heappush(pq, (nd, v, 1))
        else:
            if nd < dist0[v]:
                dist0[v] = nd
                heapq.heappush(pq, (nd, v, 0))

    print(min(dist0[N], dist1[N]))

main()

